readings=[];questions=[]
def book(key,title,chapter,theme,paragraphs,ids,en,pt,prompt,options,answer,explanation):
 id='heritage-book-'+key
 readings.append(dict(id=id,title=title,kind='book',chapter=chapter,map='library',author='Síntese didática original de VOICES, com fontes identificadas. Falas dos moradores são ficcionais; fichas históricas não são citações.',theme=theme,paragraphs=paragraphs,en=en,pt=pt,sourceIds=ids,questionId='heritage-history-'+key+'-6'))
 for grade in [6,7,8]:
  correct=(answer+grade-6)%len(options);opts=options[-(grade-6):]+options[:-(grade-6)] if grade>6 else options
  questions.append(dict(id='heritage-history-'+key+'-'+str(grade),chapter=chapter,grade=grade,subject='history',readingId=id,prompt=prompt,options=opts,correct=correct,explanation=explanation,sourceIds=ids))
book('nina','Nina Simone: piano, voz e coragem',1,'Música e direitos civis',[
'Nina Simone (1933–2003) nasceu Eunice Kathleen Waymon. Estudou piano e desenvolveu uma linguagem que aproximava música clássica, jazz e blues.',
'Seu trabalho também se ligou à luta pelos direitos civis nos Estados Unidos. A formação musical e o posicionamento público são partes distintas de sua história.',
'Na estação do jogo, compare piano, voz e intenção. Os sons são exercícios originais de VOICES; não são gravações de Nina Simone nem reproduções de suas canções.'],['heritage_nina'],'She played the piano and sang.','Ela tocava piano e cantava.','Qual descrição reconhece a formação de Nina Simone?', ['Uma cantora que nunca tocou instrumento.','Uma pianista e cantora que aproximou diferentes linguagens musicais.','Uma artista que trabalhou exclusivamente com rock.','Uma escritora que não teve carreira musical.'],1,'A leitura apresenta o piano, o canto e relações entre música clássica, jazz e blues. Ela não cabe em uma única etiqueta.')
book('tim','Tim Maia: caminhos do soul brasileiro',1,'Voz, autoria e circulação',[
'Tim Maia (1942–1998), cantor e compositor do Rio de Janeiro, é uma referência do soul no Brasil. Sua carreira reuniu voz, composição e trabalho de banda.',
'Ele viveu nos Estados Unidos, estudou inglês e cantou com The Ideals. Em 1970, lançou seu primeiro LP e gravou com Elis Regina.',
'Uma ficha de disco identifica quem compôs e quem interpretou. Na oficina, o grupo cria uma frase própria: não imita uma gravação de Tim Maia.'],['heritage_tim','heritage_rock'],'We can credit the singer and the composer.','Podemos creditar quem canta e quem compõe.','O que uma ficha musical cuidadosa distingue?', ['Cantor e compositor, sem supor que sejam sempre a mesma pessoa.','O volume alto e o baixo como nomes de artistas.','Todo disco como obra de um único autor.','O título da música como substituto de todos os créditos.'],0,'Interpretar e compor são atividades diferentes. A discografia consultada registra obras próprias e obras de outros autores.')
book('king','Martin Luther King Jr.: direitos e ação coletiva',5,'Cidadania e participação',[
'Martin Luther King Jr. (1929–1968) foi uma liderança do movimento pelos direitos civis nos Estados Unidos. Defendeu a ação não violenta contra a segregação racial.',
'Em 1964, recebeu o Nobel da Paz. Campanhas, boicotes e marchas foram construídos por muitas pessoas; uma liderança não realiza uma transformação sozinha.',
'Na assembleia ficcional, escute propostas e registre quem participou. O retrato histórico apresenta informação documental; nenhuma fala foi inventada como citação de King.'],['heritage_king'],'People worked together for civil rights.','Pessoas trabalharam juntas pelos direitos civis.','Qual legenda situa corretamente a atuação de King?', ['Criou sozinho todos os direitos humanos.','Trabalhou somente com ciência espacial.','Participou de um movimento coletivo e defendeu ações não violentas.','Recebeu o Nobel de Literatura por escrever romances.'],2,'A leitura apresenta uma liderança dentro de um movimento, a não violência e o Nobel da Paz, sem apagar outros participantes.')
book('machado','Machado de Assis: quem está contando?',3,'Literatura e leitura crítica',[
'Machado de Assis (1839–1908) escreveu romances, contos, crônicas, poesia e teatro. Trabalhou também como tipógrafo, revisor e jornalista.',
'Foi eleito primeiro presidente da Academia Brasileira de Letras, em 1897. Memórias póstumas de Brás Cubas é um de seus romances.',
'Ravi propõe separar autor e narrador: a pessoa que escreve constrói uma voz para contar. Esta atividade é do jogo; não é um trecho nem uma fala de Machado.'],['heritage_machado'],'The author creates a narrator.','O autor cria um narrador.','Ao ler uma história, por que separar autor e narrador?', ['Porque todo narrador é sempre o autor real.','Porque a voz que conta é uma construção do texto.','Porque um conto não tem autoria.','Porque só poemas têm narradores.'],1,'Autor é uma pessoa real; narrador é uma voz construída. A atividade ajuda a perguntar de que perspectiva a história é contada.')
book('carolina','Carolina Maria de Jesus: caderno e criação',3,'Diários, literatura e música',[
'Carolina Maria de Jesus (1914–1977) nasceu em Sacramento, Minas Gerais. Seu livro Quarto de despejo, publicado em 1960, reúne escrita de diário.',
'Sua produção não se limita a esse livro: escreveu em diferentes gêneros e também compôs músicas. Um álbum com suas composições foi lançado em 1961.',
'Na mesa de escrita, registre uma cena do bairro e identifique a autoria. Conhecer dificuldades históricas não significa reduzir uma escritora à pobreza.'],['heritage_carolina'],'She wrote books and composed songs.','Ela escreveu livros e compôs canções.','Qual ficha apresenta Carolina sem reduzir sua produção a uma única obra?', ['Escreveu diários, outros gêneros e também compôs músicas.','Nunca produziu música.','Escreveu somente textos científicos sobre órbitas.','Publicou um único gênero durante toda a vida.'],0,'O acervo do IMS reúne manuscritos e composições. A ficha reconhece diversidade de criação, além do livro mais conhecido.')
book('katherine','Katherine Johnson: conferir também é ciência',3,'Matemática, equipe e verificação',[
'Katherine Johnson (1918–2020) foi matemática da NASA. Seu trabalho envolveu cálculos de trajetórias de voos espaciais, junto a equipes de pesquisa.',
'Antes do voo orbital de John Glenn em 1962, ela conferiu cálculos feitos por computadores eletrônicos. Isso mostra por que revisão humana e colaboração importam.',
'No laboratório do jogo, compare dois resultados e registre a diferença. O exercício é simplificado e não representa um cálculo real de missão espacial.'],['heritage_katherine'],'We check the results together.','Conferimos os resultados juntos.','O que a revisão dos cálculos de Glenn ajuda a compreender?', ['Computadores eliminam toda necessidade de revisão.','Só uma pessoa participou do programa espacial.','Conferência humana e trabalho de equipe contribuem para a ciência.','Uma diferença entre resultados deve ser escondida.'],2,'A ficha documenta a revisão realizada por Johnson. Conferir, registrar e colaborar fazem parte do trabalho científico.')
book('rock','Blues, rock e caminhos que se encontram',1,'História da música negra',[
'Blues, rhythm and blues e gospel estão entre as tradições afro-americanas que influenciaram o rock. Nenhuma dessas histórias cabe numa origem única ou em um artista só.',
'Sister Rosetta Tharpe destacou-se como cantora e guitarrista, aproximando gospel e guitarra elétrica. O museu Rock & Roll Hall of Fame reconhece sua influência.',
'Mila propõe uma sequência original de pergunta e resposta. Compare frase, repetição e timbre; o exercício não é uma gravação histórica nem uma representação completa do blues.'],['heritage_rock','heritage_rosetta'],'Listen to the question and the answer.','Ouça a pergunta e a resposta.','Qual descrição reconhece relações históricas do rock?', ['Nasceu sem relação com tradições musicais negras.','Recebeu influências de blues, rhythm and blues e gospel.','É exatamente igual a todos esses gêneros.','Foi criado exclusivamente por um único músico.'],1,'A exposição destaca várias influências e pessoas. Relacionar tradições não significa tratá-las como a mesma música.')
book('conceicao','Conceição Evaristo: literatura e memória',5,'Autoria, perspectivas e histórias',[
'Conceição Evaristo é escritora brasileira, autora de Ponciá Vicêncio, Becos da Memória e Olhos d’água. Seus textos oferecem diferentes caminhos para ler experiências negras.',
'A estante identifica autora e título, e Ravi convida a buscar a obra completa. VOICES apresenta uma síntese; não reproduz contos nem inventa uma declaração da autora.',
'Escolha uma cena cotidiana para observar. Quem conta? O que percebe? Que ponto de vista ainda pode ser escutado? As perguntas ajudam a construir uma história original.'],['heritage_conceicao'],'Different voices can tell different stories.','Vozes diferentes podem contar histórias diferentes.','Qual atitude respeita a autoria ao apresentar uma escritora?', ['Inventar uma citação e atribuí-la à autora.','Apagar seu nome e deixar apenas o título.','Identificar autora, obra e fonte, distinguindo a atividade original.','Tratar qualquer resumo como o texto completo.'],2,'A estante reconhece Conceição Evaristo e suas obras. A atividade criativa do jogador tem autoria própria e não é uma citação.')
book('instruments','Instrumentoteca: como o som começa',1,'Observação e comparação',[
'Compare oito estudos: berimbau, atabaque, agogô, reco-reco, xequerê, cuíca, djembe e ilú. Observe forma, material e o gesto que produz o som, consultando as fichas.',
'Uma corda pode vibrar; sulcos podem ser raspados; contas podem encontrar uma cabaça. A cuíca utiliza fricção interna. O djembe está ligado a tradições da região Mandé, na África Ocidental.',
'As ilustrações são pequenas e os timbres sintetizados são aproximações educativas. Não são uma demonstração técnica nem toques de cerimônias. Som, descrição e imagem podem ser consultados separadamente.'],['heritage_capoeira','heritage_atabaque','heritage_xequere','heritage_cuica','heritage_djembe','heritage_ilu'],'Compare how each sound begins.','Compare como cada som começa.','Qual instrumento da ficha utiliza fricção de uma haste interna?', ['Agogô.','Xequerê.','Cuíca.','Berimbau.'],2,'Na cuíca, uma haste ligada à pele é friccionada por dentro. A vareta externa do reco-reco tem outra função.')
book('textiles','Tecidos, amarrações e contextos',5,'Técnica, roupa e pertencimento',[
'Kente reúne tiras tecidas, associadas a tradições Asante e Ewe, especialmente no atual Gana. Ankara utiliza algodão estampado e tem uma história de circulação e escolhas africanas.',
'Turbantes têm usos diversos. Ojá possui sentidos específicos nos candomblés e não é sinônimo de qualquer amarração. Pano da costa, fios de contas e balangandãs também pedem contexto.',
'Compare tecido e estampa, depois escreva uma legenda. Não deduza religião pela aparência, nem atribua uma cor ou um significado universal a todas as comunidades.'],['heritage_tecidos','heritage_oja','heritage_pano','heritage_contas','heritage_balangandas'],'We describe the cloth and its context.','Descrevemos o tecido e seu contexto.','Qual comparação distingue Kente de Ankara nas fichas?', ['Kente reúne tiras tecidas; Ankara apresenta algodão estampado.','Os dois nomes indicam qualquer turbante.','Kente é somente uma estampa impressa de Ankara.','Ambos identificam a religião de quem os usa.'],0,'A leitura distingue construção têxtil e estampa. Um nome de tecido não revela sozinho crença, comunidade ou uso.')
book('objects','Uma peça precisa de uma boa legenda',2,'Arte, memória e espiritualidade',[
'Uma máscara não representa todas as sociedades africanas. Algumas práticas envolvem traje, música, dança e comunidade. Madeira ou metal descrevem materiais, não uma cultura universal.',
'O Sankofa, associado a tradições Akan, pode aparecer como pássaro que olha para trás com os pés adiante. As fichas distinguem ancestralidade, criação artística e referências a orixás.',
'José Adário criou uma ferramenta de Ogum em ferro, catalogada pelo Museu Afro Brasil. Os nomes “Ibi” para ferramentas e “Patachas” para amuletos não foram confirmados nas fontes consultadas; não os tratamos como sinônimos. Patuá é um termo documentado.'],['heritage_mascaras','heritage_metal','heritage_sankofa','heritage_ferro','heritage_patua'],'A label shows what we know and what we still ask.','Uma legenda mostra o que sabemos e o que ainda perguntamos.','Qual legenda respeita os limites da pesquisa?', ['Esta máscara representa todos os povos africanos.','Todas as peças têm o mesmo uso religioso.','Identifica o contexto conhecido e registra o que não foi confirmado.','O desenho do jogo é sempre uma peça ritual autêntica.'],2,'Uma descrição responsável distingue material, autoria e contexto. Quando um termo não foi confirmado, informa a dúvida sem inventar uma equivalência.')
figures=[]
for index,(id,name,role,map,x,y) in enumerate([
('nina','Nina Simone','Pianista, cantora e compositora','room-1',13.5,3.7),('tim','Tim Maia','Cantor e compositor','chapter-1',25,11),('king','Martin Luther King Jr.','Liderança dos direitos civis','room-5',4,3.5),('machado','Machado de Assis','Escritor e jornalista','library',13,4.8),('carolina','Carolina Maria de Jesus','Escritora e compositora','library',9,13),('katherine','Katherine Johnson','Matemática e pesquisadora','room-3',12.5,7.5)]):
 b=next(b for b in readings if b['id']=='heritage-book-'+id)
 figures.append(dict(id=id,index=index,name=name,role=role,map=map,x=x,y=y,character='history-'+id,readingId=b['id'],sourceIds=b['sourceIds'],facts=b['paragraphs'][:2],enFacts=[b['en'],'This is an original educational summary, not a historical quotation.']))
entries=[]
def item(index,title,map,x,y,description,sourceIds,readingId,mechanism=None):
 entries.append(dict(id='heritage-item-'+str(index),index=index,title=title,map=map,x=x,y=y,description=description,sourceIds=sourceIds,readingId='heritage-book-'+readingId,mechanism=mechanism))
item(40,'Berimbau','chapter-1',6.8,11.2,'Arco, arame e cabaça. A corda vibra; a cabaça ajuda a ressoar. Na capoeira, toques e escuta participam do jogo.',['heritage_capoeira'],'instruments','corda')
item(41,'Atabaque','chapter-1',4,11.2,'Tambor alongado, com pele e corpo de madeira. Participa de manifestações diversas; a ficha precisa identificar cada contexto.',['heritage_atabaque'],'instruments','pele')
item(42,'Agogô','room-1',10,5.5,'Este estudo tem duas campânulas metálicas e uma baqueta. Compare as duas alturas: existem outras configurações do instrumento.',['heritage_capoeira'],'instruments','metal')
item(43,'Reco-reco','room-1',13.5,5.9,'A vareta percorre sulcos no corpo de bambu. O som vem do atrito e da sequência de pequenos contatos.',['heritage_capoeira'],'instruments','raspagem')
item(44,'Xequerê','room-1',10,8.3,'Uma rede de contas envolve a cabaça. Ao mover o instrumento, as contas encontram sua superfície. Os usos variam conforme o contexto.',['heritage_xequere'],'instruments','contas')
item(45,'Cuíca','room-1',13.5,8.3,'A haste fica por dentro, ligada à pele. Sua fricção produz o som; ela não é uma baqueta externa.',['heritage_cuica'],'instruments','fricção')
item(46,'Djembe','chapter-2',19,13.5,'Tambor em cálice, com pele e cordas de tensão. A referência situa o instrumento na região Mandé, na África Ocidental.',['heritage_djembe'],'instruments','pele')
item(47,'Ilú','chapter-2',19,15.3,'O estudo mostra tambor e apoio. Oficinas no Recife ensinam o instrumento e discutem respeito às tradições afro-brasileiras.',['heritage_ilu'],'instruments','pele')
item(48,'Turbante e ojá: contexto importa','market',26.5,6.5,'Turbantes têm usos diversos. Ojá tem sentidos específicos nos candomblés. Esta amarração original não identifica a religião de ninguém.',['heritage_oja'],'textiles')
item(49,'Fio de contas / guias','room-2',12,9.5,'Colares podem expressar vínculos religiosos e pertencimento. Configurações e significados variam; a cor sozinha não basta para interpretar.',['heritage_contas'],'textiles')
item(50,'Pano da costa','market',18.5,9.3,'Pano retangular com variedades de tecelagem e formas de vestir. Conhecer a peça envolve reconhecer quem faz, usa e transmite saberes.',['heritage_pano'],'textiles')
item(51,'Kente: tiras tecidas','market',18.5,4.7,'Tradições Asante e Ewe, especialmente em Gana. Tiras estreitas são tecidas e unidas; o desenho se forma na tecelagem.',['heritage_tecidos'],'textiles')
item(52,'Ankara: algodão estampado','market',18.5,7,'O algodão recebe motivos estampados. A história envolve circulação, comércio e escolhas criativas africanas; não é Kente impresso.',['heritage_tecidos'],'textiles')
item(53,'Penca de balangandãs','room-2',12,7,'Suporte metálico com diferentes pingentes. O conjunto tem autoria, trajetória e sentidos sociais e simbólicos situados.',['heritage_balangandas'],'textiles')
item(54,'Máscara: estudo em madeira','chapter-2',4,12.8,'Esta é uma ilustração original. Máscaras podem integrar traje, música e movimento; uma forma não representa um continente inteiro.',['heritage_mascaras'],'objects')
item(55,'Máscara: estudo em metal','chapter-2',6.5,12.8,'Uma ficha do Smithsonian documenta máscara em liga de cobre. Este desenho próprio estuda material; não é réplica daquela peça.',['heritage_metal'],'objects')
item(56,'Memória e ancestralidade','room-2',20,11.5,'Escultura educativa original sobre memória. Não corresponde a um povo ou objeto ritual específico; ancestralidade e orixás são categorias distintas.',['heritage_ancestral'],'objects')
item(57,'Criação artística: referência a Ogum','room-2',20,9.2,'Figura artística original, identificada como estudo. Não é peça consagrada nem cópia de escultura. A referência documental próxima apresenta ferramenta de Ogum em ferro.',['heritage_ferro'],'objects')
item(58,'Sankofa: aprender com o passado','chapter-5',3.8,11.5,'O pássaro olha para trás e mantém os pés adiante. Em tradições Akan, Sankofa relaciona memória e aprendizagem para seguir.',['heritage_sankofa'],'objects')
item(59,'Ferramentas de ferro e autoria','room-2',9.5,9.5,'José Adário assina uma ferramenta de Ogum em ferro no Museu Afro Brasil. “Ibi” não foi confirmado como nome dessa categoria.',['heritage_ferro'],'objects')
item(60,'Amuletos e patuás','room-2',9.5,7,'Fé, memória e intenção podem integrar um amuleto. Patuá é documentado; “Patachas” não foi confirmado. A mostra não atribui poderes ou bônus de jogo.',['heritage_patua'],'objects')
residents=[dict(id='mila',character='mila',name='Mila',role='Educadora musical e guitarrista',map='chapter-1',x=12,y=12,tasks=['heritage-item-40','rhythm-listen','heritage-rock-station'],lines=[dict(speaker='mila',pt='Vamos tocar uma frase e deixar espaço pra outra pessoa responder?',en='Let’s play a phrase and leave room for an answer.'),dict(speaker='mila',pt='No blues e no rock há muitas histórias de músicos negros. A estante apresenta Sister Rosetta Tharpe e suas influências.',en='The reading introduces Sister Rosetta Tharpe and musical influences.'),dict(speaker='mila',pt='Nina Simone estudou piano. Tim Maia cantou e compôs. As fichas mostram caminhos diferentes, sem colocar todo mundo na mesma caixa.',en='The records show different musical paths.'),dict(speaker='mila',pt='Esse som é nosso exercício original. Na ficha você encontra as referências históricas, com os créditos.',en='This sound is our original exercise. The records credit the historical references.')]),dict(id='ravi',character='ravi',name='Ravi',role='Livreiro e mediador de leitura',map='library',x=13,y=11.8,tasks=['library-history-section','reading-right','heritage-reading-desk'],lines=[dict(speaker='ravi',pt='Separei um lugar pra quem quer ler devagar. Qual história chamou sua atenção?',en='I saved a place for slow reading. Which story caught your attention?'),dict(speaker='ravi',pt='Machado trabalhou como revisor. Uma pergunta boa pra começar é: quem está contando essa história?',en='Machado worked as a proofreader. Who is telling this story?'),dict(speaker='ravi',pt='Carolina também compôs músicas. Conhecer um livro não revela toda a criação de uma pessoa.',en='Carolina also composed songs. One book does not show all of a person’s work.'),dict(speaker='ravi',pt='Aqui tem Conceição Evaristo e registros de artistas e cientistas. Cada ficha aponta a fonte pra você continuar a descoberta.',en='The records point to sources so you can keep exploring.')])]
