expanded=json.loads((root/'assets/tilesets/expanded-manifest.json').read_text())['props']
(root/'js/heritage-content.js').write_text('(function(){\'use strict\';const V=window.V;V.heritageContent='+json.dumps(content,ensure_ascii=False,separators=(',',':'))+';V.sceneAssets.push(...'+json.dumps([{**p,'family':'expanded','solid':bool(p['solidFootprint'])} for p in expanded],ensure_ascii=False,separators=(',',':'))+');V.sceneAssets.push(...V.heritageContent.figures.map(f=>({family:\'history\',index:f.index,name:\'Retrato educativo · \'+f.name,category:\'história\',solid:false})));})();\n')
(root/'data/heritage-sources.json').write_text(json.dumps(dict(version='1.6',author='Pesquisa e redação original de VOICES',sources=sources,editorialNotes=['Ibi como categoria de ferramentas e Patachas como amuletos não foram confirmados. Ibá, ibiri e patuá são termos distintos, sem correção presumida.','Retratos históricos são representações educativas originais. Diálogos de moradores são ficcionais; não há falas em primeira pessoa atribuídas a figuras reais.','Música sintetizada original, sem gravações comerciais ou toques cerimoniais.']),ensure_ascii=False,indent=2)+'\n')
